	SHLXQ BX, DX, DX

sequenceDecs_decode_bmi2_fill_2_end:
	// Update literal length
	MOVQ    DI, AX
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	MOVQ    DX, R14
	SHLXQ   CX, DX, DX
	ADDQ    CX, BX
	SHRQ    $0x01, R14
	XORQ    $0x3f, CX
	SHRXQ   CX, R14, R14
	ADDQ    R14, AX
	MOVQ    AX, (R10)
	CMPQ    16(SP), $0x00
	JZ      sequenceDecs_decode_bmi2_skip_update
	LEAQ    (DI)(R8*1), AX
	ADDQ    R9, AX
	MOVBQZX AL, AX
	MOVQ    DX, CX
	SHLXQ   AX, DX, DX
	ADDQ    AX, BX
	SHRQ    $0x01, CX
	XORQ    $0x3f, AX
	SHRXQ   AX, CX, CX

	// Update Offset State
	BZHIQ R9, CX, AX
	SHRXQ R9, CX, CX
	SHRL  $0x10, R9
	ADDQ  AX, R9

	// Load ctx.ofTable
	MOVQ X2, AX
	MOVQ (AX)(R9*8), R9

	// Update Match Length State
	BZHIQ R8, CX, AX
	SHRXQ R8, CX, CX
	SHRL  $0x10, R8
	ADDQ  AX, R8

	// Load ctx.mlTable
	MOVQ X1, AX
	MOVQ (AX)(R8*8), R8

	// Update Literal Length State
	MOVL DI, AX
	SHRL $0x10, AX
	ADDQ CX, AX

	// Load ctx.llTable
	MOVQ X0, CX
	MOVQ (CX)(AX*8), DI

sequenceDecs_decode_bmi2_skip_update:
	MOVQ X3, AX

	// Adjust offset
	MOVQ 16(R10), CX
	CMPQ AX, $0x01
	JBE  sequenceDecs_decode_bmi2_adjust_offsetB_1_or_0
	MOVQ R12, R13
	MOVQ R11, R12
	MOVQ CX, R11
	JMP  sequenceDecs_decode_bmi2_after_adjust

sequenceDecs_decode_bmi2_adjust_offsetB_1_or_0:
	CMPQ (R10), $0x00000000
	JNE  sequenceDecs_decode_bmi2_adjust_offset_maybezero
	INCQ CX
	JMP  sequenceDecs_decode_bmi2_adjust_offset_nonzero

sequenceDecs_decode_bmi2_adjust_offset_maybezero:
	TESTQ CX, CX
	JNZ   sequenceDecs_decode_bmi2_adjust_offset_nonzero
	MOVQ  R11, CX
	JMP   sequenceDecs_decode_bmi2_after_adjust

sequenceDecs_decode_bmi2_adjust_offset_nonzero:
	CMPQ CX, $0x01
	JB   sequenceDecs_decode_bmi2_adjust_zero
	JEQ  sequenceDecs_decode_bmi2_adjust_one
	CMPQ CX, $0x02
	JA   sequenceDecs_decode_bmi2_adjust_three
	JMP  sequenceDecs_decode_bmi2_adjust_two

sequenceDecs_decode_bmi2_adjust_zero:
	MOVQ R11, AX
	JMP  sequenceDecs_decode_bmi2_adjust_test_temp_valid

sequenceDecs_decode_bmi2_adjust_one:
	MOVQ R12, AX
	JMP  sequenceDecs_decode_bmi2_adjust_test_temp_valid

sequenceDecs_decode_bmi2_adjust_two:
	MOVQ R13, AX
	JMP  sequenceDecs_decode_bmi2_adjust_test_temp_valid

sequenceDecs_decode_bmi2_adjust_three:
	LEAQ -1(R11), AX

sequenceDecs_decode_bmi2_adjust_test_temp_valid:
	TESTQ AX, AX
	JNZ   sequenceDecs_decode_bmi2_adjust_temp_valid
	MOVQ  $0x00000001, AX

sequenceDecs_decode_bmi2_adjust_temp_valid:
	CMPQ    CX, $0x01
	CMOVQNE R12, R13
	MOVQ    R11, R12
	MOVQ    AX, R11
	MOVQ    AX, CX

sequenceDecs_decode_bmi2_after_adjust:
	MOVQ CX, 16(R10)

	// Check values
	MOVQ  8(R10), AX
	MOVQ  (R10), R14
	LEAQ  (AX)(R14*1), R15
	MOVQ  s+0(FP), BP
	ADDQ  R15, 256(BP)
	SUBQ  R14, 24(SP)
	JS    error_not_enough_literals
	CMPQ  AX, $0x00020002
	JA    sequenceDecs_decode_bmi2_error_match_len_too_big
	TESTQ CX, CX
	JZ    sequenceDecs_decode_bmi2_check_ml_zero

sequenceDecs_decode_bmi2_match_len_ofs_ok:
	ADDQ    $0x18, R10
	DECQ    16(SP)
	JNS     sequenceDecs_decode_bmi2_main_loop
	MOVQ    s+0(FP), AX
	MOVQ    R11, 144(AX)
	MOVQ    R12, 152(AX)
	MOVQ    R13, 160(AX)
	MOVQ    24(SP), AX
	MOVQ    ctx+16(FP), CX
	MOVQ    AX, 128(CX)
	XORQ    AX, AX
	SHRXQ   BX, DX, DX
	CMPQ    BX, $0x40
	CMOVQCC AX, DX
	MOVQ    br+8(FP), AX
	MOVQ    DX, 24(AX)
	MOVB    BL, 40(AX)
	SUBQ    (SP), SI
	MOVQ    SI, 32(AX)

	// Return success
	MOVQ 16(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000000, ret+24(FP)
	RET

sequenceDecs_decode_bmi2_fill_byte_by_byte:
sequenceDecs_decode_bmi2_fill_bbb_loop:
	CMPQ    SI, (SP)
	JBE     sequenceDecs_decode_bmi2_fill_check_overread
	CMPQ    BX, $0x07
	JLE     sequenceDecs_decode_bmi2_fill_end
	SUBQ    $0x01, SI
	SUBQ    $0x08, BX
	MOVBQZX (SI), AX
	SHLXQ   BX, AX, AX
	ORQ     AX, DX
	JMP     sequenceDecs_decode_bmi2_fill_bbb_loop

sequenceDecs_decode_bmi2_fill_check_overread:
	CMPQ BX, $0x40
	JA   error_overread
	JMP  sequenceDecs_decode_bmi2_fill_end

sequenceDecs_decode_bmi2_fill_2_byte_by_byte:
sequenceDecs_decode_bmi2_fill_2_bbb_loop:
	CMPQ    SI, (SP)
	JBE     sequenceDecs_decode_bmi2_fill_2_check_overread
	CMPQ    BX, $0x07
	JLE     sequenceDecs_decode_bmi2_fill_2_end
	SUBQ    $0x01, SI
	SUBQ    $0x08, BX
	MOVBQZX (SI), AX
	SHLXQ   BX, AX, AX
	ORQ     AX, DX
	JMP     sequenceDecs_decode_bmi2_fill_2_bbb_loop

sequenceDecs_decode_bmi2_fill_2_check_overread:
	CMPQ BX, $0x40
	JA   error_overread
	JMP  sequenceDecs_decode_bmi2_fill_2_end

sequenceDecs_decode_bmi2_check_ml_zero:
	TESTQ AX, AX
	JNZ   sequenceDecs_decode_bmi2_error_match_len_ofs_mismatch
	JMP   sequenceDecs_decode_bmi2_match_len_ofs_ok

	// Return with match length error
sequenceDecs_decode_bmi2_error_match_len_ofs_mismatch:
	MOVQ 16(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000001, ret+24(FP)
	RET

	// Return with match too long error
sequenceDecs_decode_bmi2_error_match_len_too_big:
	MOVQ 16(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000002, ret+24(FP)
	RET

	// Return with match offset too long error
	MOVQ 16(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000003, ret+24(FP)
	RET

	// Return with not enough literals error
error_not_enough_literals:
	MOVQ ctx+16(FP), AX
	MOVQ 24(SP), CX
	MOVQ CX, 128(AX)
	MOVQ 16(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000004, ret+24(FP)
	RET

	// Return with overread error
error_overread:
	MOVQ 16(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 96(CX)
	MOVQ $0x00000006, ret+24(FP)
	RET

