	MOVQ 184(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_7
	MOVQ 24(SP), R11
	ADDQ R11, R13

prefetch_in_out_7:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       176(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)
	PCALIGN    $0x40

prefetch_skip_7:
main_loop:
	MOVQ (SP), R11
	LEAQ 192(AX), R12
	CMPQ R12, R11
	JAE  prefetch_skip_8
	MOVQ 8(SP), R12
	MOVQ 192(AX), R11
	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 208(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_8
	MOVQ 24(SP), R11
