prefetch_in_out_8:
	PREFETCHT0 (R13)
	PREFETCHT0 64(R13)
	MOVQ       200(AX), R11
	ADDQ       R11, R12
	MOVQ       R12, 8(SP)

prefetch_skip_8:
	MOVQ (AX), R11
	MOVQ 16(AX), R12
	MOVQ 8(AX), R13

	// Copy literals
	MOVUPS (SI), X0
	MOVUPS X0, (BX)
	CMPQ   R11, $0x10
	JA     copy_1_long

copy_1_done:
	ADDQ R11, SI
	ADDQ R11, BX
	ADDQ R11, DI

	// Check offset bounds and fast-path matches inside current buffer
	CMPQ R12, R8
	JG   error_match_off_too_big
	CMPQ R12, DI
	JA   copy_from_history

	// Copy match from the current buffer
copy_match:
	MOVQ BX, R11
	SUBQ R12, R11

	// ml <= mo
	CMPQ R13, R12
	JA   copy_overlapping_match

	// Copy non-overlapping match
	ADDQ   R13, DI
	MOVUPS (R11), X0
	MOVUPS 16(R11), X1
	MOVUPS X0, (BX)
	MOVUPS X1, 16(BX)
	CMPQ   R13, $0x20
	JA     copy_2_long
	ADDQ   R13, BX
	ADDQ   $0x18, AX
	INCQ   DX
	CMPQ   DX, CX
	JB     main_loop
	JMP    loop_finished

copy_1_long:
	MOVQ $0x00000010, R14

copy_1_loop:
	MOVUPS (SI)(R14*1), X0
	MOVUPS X0, (BX)(R14*1)
	ADDQ   $0x10, R14
	CMPQ   R14, R11
	JB     copy_1_loop
	JMP    copy_1_done

copy_2_long:
	LEAQ 32(BX), R12
	ADDQ R13, BX
	ADDQ $0x20, R11
	SUBQ $0x20, R13

copy_2:
	MOVUPS (R11), X0
	MOVUPS 16(R11), X1
	MOVUPS X0, (R12)
	MOVUPS X1, 16(R12)
	ADDQ   $0x20, R11
	ADDQ   $0x20, R12
	SUBQ   $0x20, R13
	JHI    copy_2
	JMP    handle_loop

	// Copy overlapping match
copy_overlapping_match:
	ADDQ R13, DI
	CMPQ R12, $0x10
	JB   copy_overlap_lt16
	MOVQ BX, R12
	ADDQ R13, BX

copy_3:
	MOVUPS (R11), X0
	MOVUPS X0, (R12)
	ADDQ   $0x10, R11
	ADDQ   $0x10, R12
	SUBQ   $0x10, R13
	JHI    copy_3
	JMP    handle_loop

copy_overlap_lt16:
	CMPQ R12, $0x08
	JB   copy_overlap_lt8
