	ADDQ R13, BX

copy_3_8:
	MOVQ (R11), R14
	MOVQ R14, (R12)
	ADDQ $0x08, R11
	ADDQ $0x08, R12
	SUBQ $0x08, R13
	JHI  copy_3_8
	JMP  handle_loop

copy_overlap_lt8:
	CMPQ    R12, $0x01
	JNE     copy_slow_3
	MOVQ    BX, R12
	ADDQ    R13, BX
	MOVBQZX (R11), R11
	MOVQ    R11, R14
	SHLQ    $0x08, R14
	ORQ     R14, R11
	MOVQ    R11, R14
	SHLQ    $0x10, R14
	ORQ     R14, R11
	MOVQ    R11, R14
	SHLQ    $0x20, R14
	ORQ     R14, R11

copy_3_1:
	MOVQ R11, (R12)
	ADDQ $0x08, R12
	SUBQ $0x08, R13
	JHI  copy_3_1
	JMP  handle_loop

copy_slow_3:
	MOVBQZX (R11), R12
	MOVB    R12, (BX)
	INCQ    R11
	INCQ    BX
	DECQ    R13
	JNZ     copy_slow_3
	JMP     handle_loop

	// Copy match from history (out-of-line)
copy_from_history:
	LEAQ (DI)(R10*1), R11
	CMPQ R12, R11
	JG   error_match_off_too_big
	MOVQ R12, R11
	SUBQ DI, R11
	MOVQ R9, R14
	SUBQ R11, R14
	CMPQ R13, R11
	JG   copy_all_from_history
	MOVQ R13, R11
	SUBQ $0x10, R11
	JB   copy_4_small

copy_4_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (BX)
	ADDQ   $0x10, R14
	ADDQ   $0x10, BX
	SUBQ   $0x10, R11
	JAE    copy_4_loop
	LEAQ   16(R14)(R11*1), R14
	LEAQ   16(BX)(R11*1), BX
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(BX)
	JMP    copy_4_end

copy_4_small:
	CMPQ R13, $0x03
	JE   copy_4_move_3
	CMPQ R13, $0x08
	JB   copy_4_move_4through7
	JMP  copy_4_move_8through16

copy_4_move_3:
	MOVWQZX (R14), R11
	MOVB    2(R14), R12
	MOVW    R11, (BX)
	MOVB    R12, 2(BX)
	ADDQ    R13, R14
	ADDQ    R13, BX
	JMP     copy_4_end

copy_4_move_4through7:
	MOVL (R14), R11
	MOVL -4(R14)(R13*1), R12
	MOVL R11, (BX)
	MOVL R12, -4(BX)(R13*1)
	ADDQ R13, R14
	ADDQ R13, BX
	JMP  copy_4_end

copy_4_move_8through16:
	MOVQ (R14), R11
	MOVQ -8(R14)(R13*1), R12
	MOVQ R11, (BX)
	MOVQ R12, -8(BX)(R13*1)
	ADDQ R13, R14
	ADDQ R13, BX

copy_4_end:
	ADDQ R13, DI
	ADDQ $0x18, AX
	INCQ DX
	CMPQ DX, CX
	JB   main_loop
	JMP  loop_finished

copy_all_from_history:
	MOVQ R11, R15
	SUBQ $0x10, R15
	JB   copy_5_small

copy_5_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (BX)
	ADDQ   $0x10, R14
	ADDQ   $0x10, BX
	SUBQ   $0x10, R15
	JAE    copy_5_loop
	LEAQ   16(R14)(R15*1), R14
	LEAQ   16(BX)(R15*1), BX
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(BX)
	JMP    copy_5_end

copy_5_small:
	CMPQ R11, $0x03
	JE   copy_5_move_3
	JB   copy_5_move_1or2
	CMPQ R11, $0x08
	JB   copy_5_move_4through7
	JMP  copy_5_move_8through16

copy_5_move_1or2:
	MOVB (R14), R15
	MOVB -1(R14)(R11*1), BP
	MOVB R15, (BX)
	MOVB BP, -1(BX)(R11*1)
	ADDQ R11, R14
	ADDQ R11, BX
	JMP  copy_5_end

copy_5_move_3:
	MOVWQZX (R14), R15
	MOVB    2(R14), BP
	MOVW    R15, (BX)
	MOVB    BP, 2(BX)
	ADDQ    R11, R14
	ADDQ    R11, BX
