	ADDQ R11, R12
	MOVQ R12, R13
	MOVQ 88(AX), R11
	SUBQ R11, R13
	MOVQ 16(SP), R11
	CMPQ R13, R11
	JAE  prefetch_in_out_3
	MOVQ 24(SP), R11
