copy_1_move_8through16:
	MOVQ (SI), R14
	MOVQ -8(SI)(R11*1), R15
	MOVQ R14, (BX)
	MOVQ R15, -8(BX)(R11*1)
	ADDQ R11, SI
	ADDQ R11, BX

copy_1_end:
	ADDQ R11, DI

	// Check offset bounds and fast-path matches inside current buffer
check_offset:
	CMPQ R12, R8
	JG   error_match_off_too_big
	CMPQ R12, DI
	JA   copy_from_history

	// Copy match from the current buffer
copy_match:
	MOVQ BX, R11
