copy_3_blocks:
	MOVUPS (R11), X0
	MOVUPS X0, (BX)
	ADDQ   $0x10, R11
	ADDQ   $0x10, BX
	SUBQ   $0x10, R13
	CMPQ   R13, $0x10
	JAE    copy_3_blocks
	TESTQ  R13, R13
	JZ     handle_loop
	JMP    copy_slow_3

copy_overlap_lt16:
copy_slow_3:
	MOVBQZX (R11), R12
	MOVB    R12, (BX)
	INCQ    R11
	INCQ    BX
	DECQ    R13
	JNZ     copy_slow_3
	JMP     handle_loop

	// Copy match from history (out-of-line)
copy_from_history:
	LEAQ (DI)(R10*1), R11
	CMPQ R12, R11
	JG   error_match_off_too_big
	MOVQ R12, R11
	SUBQ DI, R11
	MOVQ R9, R14
	SUBQ R11, R14
	CMPQ R13, R11
	JG   copy_all_from_history
	MOVQ R13, R11
	SUBQ $0x10, R11
	JB   copy_4_small

copy_4_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (BX)
	ADDQ   $0x10, R14
	ADDQ   $0x10, BX
	SUBQ   $0x10, R11
	JAE    copy_4_loop
	LEAQ   16(R14)(R11*1), R14
	LEAQ   16(BX)(R11*1), BX
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(BX)
	JMP    copy_4_end

copy_4_small:
	CMPQ R13, $0x03
	JE   copy_4_move_3
	CMPQ R13, $0x08
	JB   copy_4_move_4through7
	JMP  copy_4_move_8through16

copy_4_move_3:
	MOVWQZX (R14), R11
	MOVB    2(R14), R12
	MOVW    R11, (BX)
	MOVB    R12, 2(BX)
	ADDQ    R13, R14
	ADDQ    R13, BX
	JMP     copy_4_end

copy_4_move_4through7:
	MOVL (R14), R11
	MOVL -4(R14)(R13*1), R12
	MOVL R11, (BX)
	MOVL R12, -4(BX)(R13*1)
	ADDQ R13, R14
	ADDQ R13, BX
	JMP  copy_4_end

copy_4_move_8through16:
	MOVQ (R14), R11
	MOVQ -8(R14)(R13*1), R12
	MOVQ R11, (BX)
	MOVQ R12, -8(BX)(R13*1)
	ADDQ R13, R14
	ADDQ R13, BX

copy_4_end:
	ADDQ R13, DI
	ADDQ $0x18, AX
	INCQ DX
	CMPQ DX, CX
	JB   main_loop
	JMP  loop_finished

copy_all_from_history:
	MOVQ R11, R15
	SUBQ $0x10, R15
	JB   copy_5_small

copy_5_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (BX)
	ADDQ   $0x10, R14
	ADDQ   $0x10, BX
	SUBQ   $0x10, R15
	JAE    copy_5_loop
	LEAQ   16(R14)(R15*1), R14
	LEAQ   16(BX)(R15*1), BX
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(BX)
	JMP    copy_5_end

copy_5_small:
	CMPQ R11, $0x03
	JE   copy_5_move_3
	JB   copy_5_move_1or2
	CMPQ R11, $0x08
	JB   copy_5_move_4through7
	JMP  copy_5_move_8through16

copy_5_move_1or2:
	MOVB (R14), R15
	MOVB -1(R14)(R11*1), BP
	MOVB R15, (BX)
	MOVB BP, -1(BX)(R11*1)
	ADDQ R11, R14
	ADDQ R11, BX
	JMP  copy_5_end

copy_5_move_3:
	MOVWQZX (R14), R15
	MOVB    2(R14), BP
	MOVW    R15, (BX)
	MOVB    BP, 2(BX)
	ADDQ    R11, R14
	ADDQ    R11, BX
	JMP     copy_5_end

copy_5_move_4through7:
	MOVL (R14), R15
	MOVL -4(R14)(R11*1), BP
	MOVL R15, (BX)
	MOVL BP, -4(BX)(R11*1)
	ADDQ R11, R14
	ADDQ R11, BX
	JMP  copy_5_end

copy_5_move_8through16:
	MOVQ (R14), R15
	MOVQ -8(R14)(R11*1), BP
	MOVQ R15, (BX)
	MOVQ BP, -8(BX)(R11*1)
	ADDQ R11, R14
	ADDQ R11, BX

copy_5_end:
	ADDQ R11, DI
	SUBQ R11, R13
	JMP  copy_match

handle_loop:
	ADDQ $0x18, AX
	INCQ DX
	CMPQ DX, CX
	JB   main_loop

loop_finished:
	// Return value
	MOVB $0x01, ret+8(FP)

	// Update the context
	MOVQ ctx+0(FP), AX
	MOVQ DX, 24(AX)
	MOVQ DI, 104(AX)
	SUBQ 80(AX), SI
	MOVQ SI, 112(AX)
	RET

error_match_off_too_big:
	// Return value
	MOVB $0x00, ret+8(FP)

	// Update the context
	MOVQ ctx+0(FP), AX
	MOVQ DX, 24(AX)
	MOVQ DI, 104(AX)
	SUBQ 80(AX), SI
	MOVQ SI, 112(AX)
	RET

empty_seqs:
	// Return value
	MOVB $0x01, ret+8(FP)
	RET

// func sequenceDecs_decodeSync_amd64(s *sequenceDecs, br *bitReader, ctx *decodeSyncAsmContext) int
// Requires: SSE
TEXT ·sequenceDecs_decodeSync_amd64(SB), $136-32
	MOVQ    br+8(FP), CX
	MOVQ    24(CX), DX
	MOVBQZX 40(CX), BX
	MOVQ    (CX), AX
	MOVQ    32(CX), CX
	MOVQ    AX, (SP)
	LEAQ    8(AX), SI
	MOVQ    SI, 8(SP)
	LEAQ    (AX)(CX*1), SI
	MOVQ    ctx+16(FP), AX
	MOVQ    72(AX), DI
	MOVQ    80(AX), R8
	MOVQ    88(AX), R9
	MOVQ    (AX), CX
	MOVQ    CX, 16(SP)
	MOVQ    24(AX), CX
	MOVQ    CX, 24(SP)
	MOVQ    48(AX), CX
	MOVQ    CX, 32(SP)
	MOVQ    96(AX), CX
	MOVQ    CX, 40(SP)
	MOVQ    104(AX), CX
	MOVQ    CX, 48(SP)
	XORQ    CX, CX
	MOVQ    CX, 56(SP)
	MOVQ    CX, 64(SP)
	MOVQ    CX, 72(SP)
	MOVQ    112(AX), R10
	MOVQ    128(AX), CX
	MOVQ    CX, 80(SP)
	MOVQ    144(AX), R11
	MOVQ    136(AX), R12
	MOVQ    200(AX), CX
	MOVQ    CX, 104(SP)
	MOVQ    176(AX), CX
	MOVQ    CX, 96(SP)
	MOVQ    184(AX), AX
	MOVQ    AX, 88(SP)
	MOVQ    88(SP), AX
	ADDQ    AX, 96(SP)

	// Calculate pointer to s.out[cap(s.out)] (a past-end pointer)
	ADDQ R10, 80(SP)

	// outBase += outPosition
	ADDQ    R12, R10
	MOVQ    s+0(FP), AX
	MOVQ    144(AX), CX
	MOVQ    CX, 112(SP)
	MOVQ    152(AX), CX
	MOVQ    CX, 120(SP)
	MOVQ    160(AX), AX
	MOVQ    AX, 128(SP)
	PCALIGN $0x40

sequenceDecs_decodeSync_amd64_main_loop:
	// Fill bitreader to have enough for the offset and match length.
	CMPQ SI, 8(SP)
	JB   sequenceDecs_decodeSync_amd64_fill_byte_by_byte
	MOVQ BX, AX
	SHRQ $0x03, AX
	SUBQ AX, SI
	MOVQ (SI), DX
	ANDQ $0x07, BX

sequenceDecs_decodeSync_amd64_fill_end:
	// Update offset
	MOVQ    R9, AX
	MOVQ    BX, CX
	MOVQ    DX, R13
	SHLQ    CL, R13
	SHRQ    $0x01, R13
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	ADDQ    CX, BX
	XORQ    $0x3f, CX
	SHRQ    CL, R13
	ADDQ    R13, AX
	MOVQ    AX, 56(SP)

	// Update match length
	MOVQ    R8, AX
	MOVQ    BX, CX
	MOVQ    DX, R13
	SHLQ    CL, R13
	SHRQ    $0x01, R13
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	ADDQ    CX, BX
	XORQ    $0x3f, CX
	SHRQ    CL, R13
	ADDQ    R13, AX
	MOVQ    AX, 64(SP)

	// Fill bitreader to have enough for the remaining
	CMPQ SI, 8(SP)
	JB   sequenceDecs_decodeSync_amd64_fill_2_byte_by_byte
	MOVQ BX, AX
	SHRQ $0x03, AX
	SUBQ AX, SI
	MOVQ (SI), DX
	ANDQ $0x07, BX

sequenceDecs_decodeSync_amd64_fill_2_end:
	// Update literal length
	MOVQ    DI, AX
	MOVQ    BX, CX
	MOVQ    DX, R13
	SHLQ    CL, R13
	SHRQ    $0x01, R13
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	ADDQ    CX, BX
	XORQ    $0x3f, CX
	SHRQ    CL, R13
	ADDQ    R13, AX
	MOVQ    AX, 72(SP)
	MOVQ    R9, AX
	SHRQ    $0x08, AX
	MOVBQZX AL, AX
	CMPQ    40(SP), $0x00
	JZ      sequenceDecs_decodeSync_amd64_skip_update

	// Update Literal Length State
	MOVBQZX DI, R13
	SHRL    $0x10, DI
	MOVQ    BX, CX
	MOVQ    DX, R14
	SHLQ    CL, R14
	SHRQ    $0x01, R14
	ADDQ    R13, BX
	XORQ    $0x3f, R13
	MOVQ    R13, CX
	SHRQ    CL, R14
	ADDQ    R14, DI

	// Load ctx.llTable
	MOVQ 16(SP), CX
	MOVQ (CX)(DI*8), DI

	// Update Match Length State
	MOVBQZX R8, R13
	SHRL    $0x10, R8
	MOVQ    BX, CX
	MOVQ    DX, R14
	SHLQ    CL, R14
	SHRQ    $0x01, R14
	ADDQ    R13, BX
	XORQ    $0x3f, R13
	MOVQ    R13, CX
	SHRQ    CL, R14
	ADDQ    R14, R8

	// Load ctx.mlTable
	MOVQ 24(SP), CX
	MOVQ (CX)(R8*8), R8

	// Update Offset State
	MOVBQZX R9, R13
	SHRL    $0x10, R9
	MOVQ    BX, CX
	MOVQ    DX, R14
	SHLQ    CL, R14
	SHRQ    $0x01, R14
	ADDQ    R13, BX
	XORQ    $0x3f, R13
	MOVQ    R13, CX
	SHRQ    CL, R14
	ADDQ    R14, R9

	// Load ctx.ofTable
	MOVQ 32(SP), CX
	MOVQ (CX)(R9*8), R9

sequenceDecs_decodeSync_amd64_skip_update:
	// Adjust offset
	MOVQ 56(SP), CX
	CMPQ AX, $0x01
	JBE  sequenceDecs_decodeSync_amd64_adjust_offsetB_1_or_0
	MOVQ 120(SP), R13
	MOVQ 112(SP), AX
	MOVQ R13, 128(SP)
	MOVQ AX, 120(SP)
	MOVQ CX, 112(SP)

sequenceDecs_decodeSync_amd64_after_adjust:
	// Check values
	MOVQ  64(SP), AX
	MOVQ  72(SP), R13
	SUBQ  R13, 48(SP)
	JS    error_not_enough_literals
	CMPQ  AX, $0x00020002
	JA    sequenceDecs_decodeSync_amd64_error_match_len_too_big
	TESTQ CX, CX
	JZ    sequenceDecs_decodeSync_amd64_check_ml_zero

sequenceDecs_decodeSync_amd64_match_len_ofs_ok:
	// Check if we have enough space in s.out
	LEAQ 32(R13)(AX*1), R14
	ADDQ R10, R14
	CMPQ R14, 80(SP)
	JA   error_not_enough_space

	// Copy literals
	MOVUPS (R11), X0
	MOVUPS X0, (R10)
	CMPQ   R13, $0x10
	JA     copy_1_long

copy_1_done:
	ADDQ R13, R11
	ADDQ R13, R10
	ADDQ R13, R12

	// Check offset bounds and fast-path matches inside current buffer
	CMPQ CX, 104(SP)
	JG   error_match_off_too_big_save
	CMPQ CX, R12
	JA   copy_from_history

	// Copy match from the current buffer
copy_match:
	MOVQ R10, R13
	SUBQ CX, R13

	// ml <= mo
	CMPQ AX, CX
	JA   copy_overlapping_match

	// Copy non-overlapping match
	ADDQ   AX, R12
	MOVUPS (R13), X0
	MOVUPS 16(R13), X1
	MOVUPS X0, (R10)
	MOVUPS X1, 16(R10)
	CMPQ   AX, $0x20
	JA     copy_2_long
	ADDQ   AX, R10
	DECQ   40(SP)
	JNS    sequenceDecs_decodeSync_amd64_main_loop
	JMP    loop_finished

copy_1_long:
	MOVQ $0x00000010, R14

copy_1_loop:
	MOVUPS (R11)(R14*1), X0
	MOVUPS X0, (R10)(R14*1)
	ADDQ   $0x10, R14
	CMPQ   R14, R13
	JB     copy_1_loop
	JMP    copy_1_done

copy_2_long:
	LEAQ 32(R10), CX
	ADDQ AX, R10
	ADDQ $0x20, R13
	SUBQ $0x20, AX

copy_2:
	MOVUPS (R13), X0
	MOVUPS 16(R13), X1
	MOVUPS X0, (CX)
	MOVUPS X1, 16(CX)
	ADDQ   $0x20, R13
	ADDQ   $0x20, CX
	SUBQ   $0x20, AX
	JHI    copy_2
	JMP    handle_loop

	// Copy overlapping match
copy_overlapping_match:
	ADDQ AX, R12
	CMPQ CX, $0x10
	JB   copy_overlap_lt16
	MOVQ R10, CX
	ADDQ AX, R10

copy_3:
	MOVUPS (R13), X0
	MOVUPS X0, (CX)
	ADDQ   $0x10, R13
	ADDQ   $0x10, CX
	SUBQ   $0x10, AX
	JHI    copy_3
	JMP    handle_loop

copy_overlap_lt16:
	CMPQ CX, $0x08
	JB   copy_overlap_lt8
	MOVQ R10, CX
	ADDQ AX, R10

copy_3_8:
	MOVQ (R13), R14
	MOVQ R14, (CX)
	ADDQ $0x08, R13
	ADDQ $0x08, CX
	SUBQ $0x08, AX
	JHI  copy_3_8
	JMP  handle_loop

copy_overlap_lt8:
	CMPQ    CX, $0x01
	JNE     copy_slow_3
	MOVQ    R10, CX
	ADDQ    AX, R10
	MOVBQZX (R13), R13
	MOVQ    R13, R14
	SHLQ    $0x08, R14
	ORQ     R14, R13
	MOVQ    R13, R14
	SHLQ    $0x10, R14
	ORQ     R14, R13
	MOVQ    R13, R14
	SHLQ    $0x20, R14
	ORQ     R14, R13

copy_3_1:
	MOVQ R13, (CX)
	ADDQ $0x08, CX
	SUBQ $0x08, AX
	JHI  copy_3_1
	JMP  handle_loop

copy_slow_3:
	MOVBQZX (R13), CX
	MOVB    CL, (R10)
	INCQ    R13
	INCQ    R10
	DECQ    AX
	JNZ     copy_slow_3
	JMP     handle_loop

	// Copy match from history (out-of-line)
copy_from_history:
	MOVQ R12, R13
	ADDQ 88(SP), R13
	CMPQ CX, R13
	JG   error_match_off_too_big_save
	MOVQ CX, R13
	SUBQ R12, R13
	MOVQ 96(SP), R14
	SUBQ R13, R14
	CMPQ AX, R13
	JG   copy_all_from_history
	MOVQ AX, CX
	SUBQ $0x10, CX
	JB   copy_4_small

copy_4_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (R10)
	ADDQ   $0x10, R14
	ADDQ   $0x10, R10
	SUBQ   $0x10, CX
	JAE    copy_4_loop
	LEAQ   16(R14)(CX*1), R14
	LEAQ   16(R10)(CX*1), R10
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(R10)
	JMP    copy_4_end

copy_4_small:
	CMPQ AX, $0x03
	JE   copy_4_move_3
	CMPQ AX, $0x08
	JB   copy_4_move_4through7
	JMP  copy_4_move_8through16

copy_4_move_3:
	MOVWQZX (R14), CX
	MOVB    2(R14), R13
	MOVW    CX, (R10)
	MOVB    R13, 2(R10)
	ADDQ    AX, R14
	ADDQ    AX, R10
	JMP     copy_4_end

copy_4_move_4through7:
	MOVL (R14), CX
	MOVL -4(R14)(AX*1), R13
	MOVL CX, (R10)
	MOVL R13, -4(R10)(AX*1)
	ADDQ AX, R14
	ADDQ AX, R10
	JMP  copy_4_end

copy_4_move_8through16:
	MOVQ (R14), CX
	MOVQ -8(R14)(AX*1), R13
	MOVQ CX, (R10)
	MOVQ R13, -8(R10)(AX*1)
	ADDQ AX, R14
	ADDQ AX, R10

copy_4_end:
	ADDQ AX, R12
	DECQ 40(SP)
	JNS  sequenceDecs_decodeSync_amd64_main_loop
	JMP  loop_finished

copy_all_from_history:
	MOVQ R13, R15
	SUBQ $0x10, R15
	JB   copy_5_small

copy_5_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (R10)
	ADDQ   $0x10, R14
	ADDQ   $0x10, R10
	SUBQ   $0x10, R15
	JAE    copy_5_loop
	LEAQ   16(R14)(R15*1), R14
	LEAQ   16(R10)(R15*1), R10
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(R10)
	JMP    copy_5_end

copy_5_small:
	CMPQ R13, $0x03
	JE   copy_5_move_3
	JB   copy_5_move_1or2
	CMPQ R13, $0x08
	JB   copy_5_move_4through7
	JMP  copy_5_move_8through16

copy_5_move_1or2:
	MOVB (R14), R15
	MOVB -1(R14)(R13*1), BP
	MOVB R15, (R10)
	MOVB BP, -1(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10
	JMP  copy_5_end

copy_5_move_3:
	MOVWQZX (R14), R15
	MOVB    2(R14), BP
	MOVW    R15, (R10)
	MOVB    BP, 2(R10)
	ADDQ    R13, R14
	ADDQ    R13, R10
	JMP     copy_5_end

copy_5_move_4through7:
	MOVL (R14), R15
	MOVL -4(R14)(R13*1), BP
	MOVL R15, (R10)
	MOVL BP, -4(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10
	JMP  copy_5_end

copy_5_move_8through16:
	MOVQ (R14), R15
	MOVQ -8(R14)(R13*1), BP
	MOVQ R15, (R10)
	MOVQ BP, -8(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10

copy_5_end:
	ADDQ R13, R12
	SUBQ R13, AX
	JMP  copy_match

error_match_off_too_big_save:
	MOVQ ctx+16(FP), AX
	MOVQ CX, 224(AX)
	JMP  error_match_off_too_big

handle_loop:
	DECQ 40(SP)
	JNS  sequenceDecs_decodeSync_amd64_main_loop

loop_finished:
	MOVQ s+0(FP), AX
	MOVQ 112(SP), CX
	MOVQ CX, 144(AX)
	MOVQ 120(SP), CX
	MOVQ CX, 152(AX)
	MOVQ 128(SP), CX
	MOVQ CX, 160(AX)
	MOVQ 48(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 104(CX)
	MOVQ br+8(FP), AX
	MOVQ DX, 24(AX)
	MOVB BL, 40(AX)
	SUBQ (SP), SI
	MOVQ SI, 32(AX)

	// s.seqSize += outPosition - ctx.outPosition
	MOVQ ctx+16(FP), AX
	MOVQ s+0(FP), CX
	MOVQ R12, DX
	SUBQ 136(AX), DX
	ADDQ DX, 256(CX)

	// Update the context
	MOVQ ctx+16(FP), AX
	MOVQ R12, 136(AX)
	MOVQ 144(AX), CX
	SUBQ CX, R11
	MOVQ R11, 168(AX)

	// Return success
	MOVQ $0x00000000, ret+24(FP)
	RET

sequenceDecs_decodeSync_amd64_fill_byte_by_byte:
sequenceDecs_decodeSync_amd64_fill_bbb_loop:
	CMPQ    SI, (SP)
	JBE     sequenceDecs_decodeSync_amd64_fill_check_overread
	CMPQ    BX, $0x07
	JLE     sequenceDecs_decodeSync_amd64_fill_end
	SUBQ    $0x01, SI
	SUBQ    $0x08, BX
	SHLQ    $0x08, DX
	MOVBQZX (SI), AX
	ORQ     AX, DX
	JMP     sequenceDecs_decodeSync_amd64_fill_bbb_loop

sequenceDecs_decodeSync_amd64_fill_check_overread:
	CMPQ BX, $0x40
	JA   error_overread
	JMP  sequenceDecs_decodeSync_amd64_fill_end

sequenceDecs_decodeSync_amd64_fill_2_byte_by_byte:
sequenceDecs_decodeSync_amd64_fill_2_bbb_loop:
	CMPQ    SI, (SP)
	JBE     sequenceDecs_decodeSync_amd64_fill_2_check_overread
	CMPQ    BX, $0x07
	JLE     sequenceDecs_decodeSync_amd64_fill_2_end
	SUBQ    $0x01, SI
	SUBQ    $0x08, BX
	SHLQ    $0x08, DX
	MOVBQZX (SI), AX
	ORQ     AX, DX
	JMP     sequenceDecs_decodeSync_amd64_fill_2_bbb_loop

sequenceDecs_decodeSync_amd64_fill_2_check_overread:
	CMPQ BX, $0x40
	JA   error_overread
	JMP  sequenceDecs_decodeSync_amd64_fill_2_end

sequenceDecs_decodeSync_amd64_adjust_offsetB_1_or_0:
	CMPQ 72(SP), $0x00000000
	JNE  sequenceDecs_decodeSync_amd64_adjust_offset_maybezero
	INCQ CX
	JMP  sequenceDecs_decodeSync_amd64_adjust_offset_nonzero

sequenceDecs_decodeSync_amd64_adjust_offset_maybezero:
	TESTQ CX, CX
	JNZ   sequenceDecs_decodeSync_amd64_adjust_offset_nonzero
	MOVQ  112(SP), CX
	JMP   sequenceDecs_decodeSync_amd64_after_adjust

sequenceDecs_decodeSync_amd64_adjust_offset_nonzero:
	CMPQ CX, $0x01
	JEQ  sequenceDecs_decodeSync_amd64_adjust_one
	CMPQ CX, $0x02
	JEQ  sequenceDecs_decodeSync_amd64_adjust_two
	MOVQ 112(SP), AX
	DECQ AX
	JNZ  sequenceDecs_decodeSync_amd64_adjust_shift_all
	MOVQ $0x00000001, AX
	JMP  sequenceDecs_decodeSync_amd64_adjust_shift_all

sequenceDecs_decodeSync_amd64_adjust_one:
	MOVQ 120(SP), AX
	MOVQ 112(SP), CX
	MOVQ CX, 120(SP)
	MOVQ AX, 112(SP)
	MOVQ AX, CX
	JMP  sequenceDecs_decodeSync_amd64_after_adjust

sequenceDecs_decodeSync_amd64_adjust_two:
	MOVQ 128(SP), AX

sequenceDecs_decodeSync_amd64_adjust_shift_all:
	MOVQ 120(SP), CX
	MOVQ 112(SP), R13
	MOVQ CX, 128(SP)
	MOVQ R13, 120(SP)
	MOVQ AX, 112(SP)
	MOVQ AX, CX
	JMP  sequenceDecs_decodeSync_amd64_after_adjust

sequenceDecs_decodeSync_amd64_check_ml_zero:
	TESTQ AX, AX
	JNZ   sequenceDecs_decodeSync_amd64_error_match_len_ofs_mismatch
	JMP   sequenceDecs_decodeSync_amd64_match_len_ofs_ok

	// Return with match length error
sequenceDecs_decodeSync_amd64_error_match_len_ofs_mismatch:
	MOVQ 64(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 216(CX)
	MOVQ $0x00000001, ret+24(FP)
	RET

	// Return with match too long error
sequenceDecs_decodeSync_amd64_error_match_len_too_big:
	MOVQ ctx+16(FP), AX
	MOVQ 64(SP), CX
	MOVQ CX, 216(AX)
	MOVQ $0x00000002, ret+24(FP)
	RET

	// Return with match offset too long error
error_match_off_too_big:
	MOVQ ctx+16(FP), AX
	MOVQ R12, 136(AX)
	MOVQ $0x00000003, ret+24(FP)
	RET

	// Return with not enough literals error
error_not_enough_literals:
	MOVQ ctx+16(FP), AX
	MOVQ 48(SP), CX
	MOVQ CX, 104(AX)
	MOVQ 72(SP), CX
	MOVQ CX, 208(AX)
	MOVQ $0x00000004, ret+24(FP)
	RET

	// Return with overread error
error_overread:
	MOVQ $0x00000006, ret+24(FP)
	RET

	// Return with not enough output space error
error_not_enough_space:
	MOVQ ctx+16(FP), AX
	MOVQ 72(SP), CX
	MOVQ CX, 208(AX)
	MOVQ 64(SP), CX
	MOVQ CX, 216(AX)
	MOVQ R12, 136(AX)
	MOVQ $0x00000005, ret+24(FP)
	RET

// func sequenceDecs_decodeSync_56_amd64(s *sequenceDecs, br *bitReader, ctx *decodeSyncAsmContext) int
// Requires: SSE
TEXT ·sequenceDecs_decodeSync_56_amd64(SB), $136-32
	MOVQ    br+8(FP), CX
	MOVQ    24(CX), DX
	MOVBQZX 40(CX), BX
	MOVQ    (CX), AX
	MOVQ    32(CX), CX
	MOVQ    AX, (SP)
	LEAQ    8(AX), SI
	MOVQ    SI, 8(SP)
	LEAQ    (AX)(CX*1), SI
	MOVQ    ctx+16(FP), AX
	MOVQ    72(AX), DI
	MOVQ    80(AX), R8
	MOVQ    88(AX), R9
	MOVQ    (AX), CX
	MOVQ    CX, 16(SP)
	MOVQ    24(AX), CX
	MOVQ    CX, 24(SP)
	MOVQ    48(AX), CX
	MOVQ    CX, 32(SP)
	MOVQ    96(AX), CX
	MOVQ    CX, 40(SP)
	MOVQ    104(AX), CX
	MOVQ    CX, 48(SP)
	XORQ    CX, CX
	MOVQ    CX, 56(SP)
	MOVQ    CX, 64(SP)
	MOVQ    CX, 72(SP)
	MOVQ    112(AX), R10
	MOVQ    128(AX), CX
	MOVQ    CX, 80(SP)
	MOVQ    144(AX), R11
	MOVQ    136(AX), R12
	MOVQ    200(AX), CX
	MOVQ    CX, 104(SP)
	MOVQ    176(AX), CX
	MOVQ    CX, 96(SP)
	MOVQ    184(AX), AX
	MOVQ    AX, 88(SP)
	MOVQ    88(SP), AX
	ADDQ    AX, 96(SP)

	// Calculate pointer to s.out[cap(s.out)] (a past-end pointer)
	ADDQ R10, 80(SP)

	// outBase += outPosition
	ADDQ    R12, R10
	MOVQ    s+0(FP), AX
	MOVQ    144(AX), CX
	MOVQ    CX, 112(SP)
	MOVQ    152(AX), CX
	MOVQ    CX, 120(SP)
	MOVQ    160(AX), AX
	MOVQ    AX, 128(SP)
	PCALIGN $0x40

sequenceDecs_decodeSync_56_amd64_main_loop:
	// Fill bitreader to have enough for the offset and match length.
	CMPQ SI, 8(SP)
	JB   sequenceDecs_decodeSync_56_amd64_fill_byte_by_byte
	MOVQ BX, AX
	SHRQ $0x03, AX
	SUBQ AX, SI
	MOVQ (SI), DX
	ANDQ $0x07, BX

sequenceDecs_decodeSync_56_amd64_fill_end:
	// Update offset
	MOVQ    R9, AX
	MOVQ    BX, CX
	MOVQ    DX, R13
	SHLQ    CL, R13
	SHRQ    $0x01, R13
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	ADDQ    CX, BX
	XORQ    $0x3f, CX
	SHRQ    CL, R13
	ADDQ    R13, AX
	MOVQ    AX, 56(SP)

	// Update match length
	MOVQ    R8, AX
	MOVQ    BX, CX
	MOVQ    DX, R13
	SHLQ    CL, R13
	SHRQ    $0x01, R13
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	ADDQ    CX, BX
	XORQ    $0x3f, CX
	SHRQ    CL, R13
	ADDQ    R13, AX
	MOVQ    AX, 64(SP)

	// Update literal length
	MOVQ    DI, AX
	MOVQ    BX, CX
	MOVQ    DX, R13
	SHLQ    CL, R13
	SHRQ    $0x01, R13
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	ADDQ    CX, BX
	XORQ    $0x3f, CX
	SHRQ    CL, R13
	ADDQ    R13, AX
	MOVQ    AX, 72(SP)
	MOVQ    R9, AX
	SHRQ    $0x08, AX
	MOVBQZX AL, AX
	CMPQ    40(SP), $0x00
	JZ      sequenceDecs_decodeSync_56_amd64_skip_update

	// Update Literal Length State
	MOVBQZX DI, R13
	SHRL    $0x10, DI
	MOVQ    BX, CX
	MOVQ    DX, R14
	SHLQ    CL, R14
	SHRQ    $0x01, R14
	ADDQ    R13, BX
	XORQ    $0x3f, R13
	MOVQ    R13, CX
	SHRQ    CL, R14
	ADDQ    R14, DI

	// Load ctx.llTable
	MOVQ 16(SP), CX
	MOVQ (CX)(DI*8), DI

	// Update Match Length State
	MOVBQZX R8, R13
	SHRL    $0x10, R8
	MOVQ    BX, CX
	MOVQ    DX, R14
	SHLQ    CL, R14
	SHRQ    $0x01, R14
	ADDQ    R13, BX
	XORQ    $0x3f, R13
	MOVQ    R13, CX
	SHRQ    CL, R14
	ADDQ    R14, R8

	// Load ctx.mlTable
	MOVQ 24(SP), CX
	MOVQ (CX)(R8*8), R8

	// Update Offset State
	MOVBQZX R9, R13
	SHRL    $0x10, R9
	MOVQ    BX, CX
	MOVQ    DX, R14
	SHLQ    CL, R14
	SHRQ    $0x01, R14
	ADDQ    R13, BX
	XORQ    $0x3f, R13
	MOVQ    R13, CX
	SHRQ    CL, R14
	ADDQ    R14, R9

	// Load ctx.ofTable
	MOVQ 32(SP), CX
	MOVQ (CX)(R9*8), R9

sequenceDecs_decodeSync_56_amd64_skip_update:
	// Adjust offset
	MOVQ 56(SP), CX
	CMPQ AX, $0x01
	JBE  sequenceDecs_decodeSync_56_amd64_adjust_offsetB_1_or_0
