	JA     copy_2_long
	ADDQ   AX, R10
	DECQ   40(SP)
	JNS    sequenceDecs_decodeSync_56_amd64_main_loop
	JMP    loop_finished

copy_1_long:
	MOVQ $0x00000010, R14

copy_1_loop:
	MOVUPS (R11)(R14*1), X0
	MOVUPS X0, (R10)(R14*1)
	ADDQ   $0x10, R14
	CMPQ   R14, R13
	JB     copy_1_loop
	JMP    copy_1_done

copy_2_long:
	LEAQ 32(R10), CX
	ADDQ AX, R10
	ADDQ $0x20, R13
	SUBQ $0x20, AX

copy_2:
	MOVUPS (R13), X0
	MOVUPS 16(R13), X1
	MOVUPS X0, (CX)
	MOVUPS X1, 16(CX)
	ADDQ   $0x20, R13
	ADDQ   $0x20, CX
	SUBQ   $0x20, AX
	JHI    copy_2
	JMP    handle_loop

	// Copy overlapping match
copy_overlapping_match:
	ADDQ AX, R12
	CMPQ CX, $0x10
	JB   copy_overlap_lt16
	MOVQ R10, CX
	ADDQ AX, R10

copy_3:
	MOVUPS (R13), X0
	MOVUPS X0, (CX)
	ADDQ   $0x10, R13
	ADDQ   $0x10, CX
	SUBQ   $0x10, AX
	JHI    copy_3
	JMP    handle_loop

copy_overlap_lt16:
	CMPQ CX, $0x08
	JB   copy_overlap_lt8
	MOVQ R10, CX
	ADDQ AX, R10

copy_3_8:
	MOVQ (R13), R14
	MOVQ R14, (CX)
	ADDQ $0x08, R13
	ADDQ $0x08, CX
	SUBQ $0x08, AX
	JHI  copy_3_8
	JMP  handle_loop

copy_overlap_lt8:
	CMPQ    CX, $0x01
