	ADDQ    AX, R10
	MOVBQZX (R13), R13
	MOVQ    R13, R14
	SHLQ    $0x08, R14
	ORQ     R14, R13
	MOVQ    R13, R14
	SHLQ    $0x10, R14
	ORQ     R14, R13
	MOVQ    R13, R14
	SHLQ    $0x20, R14
	ORQ     R14, R13

copy_3_1:
	MOVQ R13, (CX)
	ADDQ $0x08, CX
	SUBQ $0x08, AX
	JHI  copy_3_1
	JMP  handle_loop

copy_slow_3:
	MOVBQZX (R13), CX
	MOVB    CL, (R10)
	INCQ    R13
	INCQ    R10
	DECQ    AX
	JNZ     copy_slow_3
	JMP     handle_loop

