	SUBQ $0x10, R15
	JB   copy_5_small

copy_5_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (R10)
	ADDQ   $0x10, R14
	ADDQ   $0x10, R10
	SUBQ   $0x10, R15
	JAE    copy_5_loop
	LEAQ   16(R14)(R15*1), R14
	LEAQ   16(R10)(R15*1), R10
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(R10)
	JMP    copy_5_end

copy_5_small:
	CMPQ R13, $0x03
	JE   copy_5_move_3
	JB   copy_5_move_1or2
	CMPQ R13, $0x08
	JB   copy_5_move_4through7
	JMP  copy_5_move_8through16

copy_5_move_1or2:
	MOVB (R14), R15
	MOVB -1(R14)(R13*1), BP
	MOVB R15, (R10)
	MOVB BP, -1(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10
	JMP  copy_5_end

copy_5_move_3:
	MOVWQZX (R14), R15
	MOVB    2(R14), BP
	MOVW    R15, (R10)
	MOVB    BP, 2(R10)
	ADDQ    R13, R14
	ADDQ    R13, R10
	JMP     copy_5_end

copy_5_move_4through7:
	MOVL (R14), R15
	MOVL -4(R14)(R13*1), BP
	MOVL R15, (R10)
	MOVL BP, -4(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10
	JMP  copy_5_end

copy_5_move_8through16:
	MOVQ (R14), R15
	MOVQ -8(R14)(R13*1), BP
	MOVQ R15, (R10)
	MOVQ BP, -8(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10

copy_5_end:
	ADDQ R13, R12
