	JMP  copy_match

error_match_off_too_big_save:
	MOVQ ctx+16(FP), AX
	MOVQ CX, 224(AX)
	JMP  error_match_off_too_big

handle_loop:
	DECQ 40(SP)
	JNS  sequenceDecs_decodeSync_56_amd64_main_loop

loop_finished:
