	MOVQ 112(SP), CX
	MOVQ CX, 144(AX)
	MOVQ 120(SP), CX
	MOVQ CX, 152(AX)
	MOVQ 128(SP), CX
	MOVQ CX, 160(AX)
	MOVQ 48(SP), AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 104(CX)
	MOVQ br+8(FP), AX
	MOVQ DX, 24(AX)
	MOVB BL, 40(AX)
	SUBQ (SP), SI
	MOVQ SI, 32(AX)

