	// Update the context
	MOVQ ctx+16(FP), AX
	MOVQ R12, 136(AX)
	MOVQ 144(AX), CX
	SUBQ CX, R11
	MOVQ R11, 168(AX)

	// Return success
	MOVQ $0x00000000, ret+24(FP)
	RET

sequenceDecs_decodeSync_56_amd64_fill_byte_by_byte:
sequenceDecs_decodeSync_56_amd64_fill_bbb_loop:
	CMPQ    SI, (SP)
