	// Update match length
	MOVQ    R8, AX
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	MOVQ    DX, R13
	SHLXQ   CX, DX, DX
	ADDQ    CX, BX
	SHRQ    $0x01, R13
	XORQ    $0x3f, CX
	SHRXQ   CX, R13, R13
	ADDQ    R13, AX
	MOVQ    AX, X5

	// Fill bitreader to have enough for the remaining
	CMPQ  SI, 8(SP)
	JB    sequenceDecs_decodeSync_bmi2_fill_2_byte_by_byte
	MOVQ  BX, AX
	SHRQ  $0x03, AX
	SUBQ  AX, SI
	MOVQ  (SI), DX
	ANDQ  $0x07, BX
	SHLXQ BX, DX, DX

sequenceDecs_decodeSync_bmi2_fill_2_end:
	// Update literal length
	MOVQ    DI, AX
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	MOVQ    DX, R13
	SHLXQ   CX, DX, DX
	ADDQ    CX, BX
	SHRQ    $0x01, R13
	XORQ    $0x3f, CX
	SHRXQ   CX, R13, R13
	ADDQ    R13, AX
	MOVQ    AX, X6
	CMPQ    16(SP), $0x00
	JZ      sequenceDecs_decodeSync_bmi2_skip_update
	LEAQ    (DI)(R8*1), AX
	ADDQ    R9, AX
	MOVBQZX AL, AX
	MOVQ    DX, CX
	SHLXQ   AX, DX, DX
	ADDQ    AX, BX
	SHRQ    $0x01, CX
	XORQ    $0x3f, AX
	SHRXQ   AX, CX, CX

	// Update Offset State
	BZHIQ R9, CX, AX
	SHRXQ R9, CX, CX
	SHRL  $0x10, R9
	ADDQ  AX, R9

	// Load ctx.ofTable
	MOVQ X2, AX
	MOVQ (AX)(R9*8), R9

	// Update Match Length State
	BZHIQ R8, CX, AX
	SHRXQ R8, CX, CX
	SHRL  $0x10, R8
	ADDQ  AX, R8

	// Load ctx.mlTable
	MOVQ X1, AX
	MOVQ (AX)(R8*8), R8

	// Update Literal Length State
	MOVL DI, AX
	SHRL $0x10, AX
	ADDQ CX, AX

	// Load ctx.llTable
	MOVQ X0, CX
	MOVQ (CX)(AX*8), DI

sequenceDecs_decodeSync_bmi2_skip_update:
	MOVQ X10, AX

	// Adjust offset
	MOVQ  X4, CX
	CMPQ  AX, $0x01
	JBE   sequenceDecs_decodeSync_bmi2_adjust_offsetB_1_or_0
	MOVOA X8, X9
	MOVOA X7, X8
	MOVQ  CX, X7

sequenceDecs_decodeSync_bmi2_after_adjust:
	// Check values
	MOVQ  X5, AX
	MOVQ  X6, R13
	MOVQ  X3, R14
	SUBQ  R13, R14
	MOVQ  R14, X3
	JS    error_not_enough_literals
	CMPQ  AX, $0x00020002
	JA    sequenceDecs_decodeSync_bmi2_error_match_len_too_big
	TESTQ CX, CX
	JZ    sequenceDecs_decodeSync_bmi2_check_ml_zero

sequenceDecs_decodeSync_bmi2_match_len_ofs_ok:
	// Check if we have enough space in s.out
	LEAQ 32(R13)(AX*1), R14
	ADDQ R10, R14
	CMPQ R14, 24(SP)
	JA   error_not_enough_space

	// Copy literals
	MOVUPS (R11), X4
	MOVUPS X4, (R10)
	CMPQ   R13, $0x10
	JA     copy_1_long

copy_1_done:
	ADDQ R13, R11
	ADDQ R13, R10
	ADDQ R13, R12

	// Check offset bounds and fast-path matches inside current buffer
	CMPQ CX, 48(SP)
	JG   error_match_off_too_big_save
	CMPQ CX, R12
	JA   copy_from_history

	// Copy match from the current buffer
copy_match:
	MOVQ R10, R13
	SUBQ CX, R13

	// ml <= mo
	CMPQ AX, CX
	JA   copy_overlapping_match

	// Copy non-overlapping match
	ADDQ   AX, R12
	MOVUPS (R13), X4
	MOVUPS 16(R13), X5
	MOVUPS X4, (R10)
	MOVUPS X5, 16(R10)
	CMPQ   AX, $0x20
	JA     copy_2_long
	ADDQ   AX, R10
	DECQ   16(SP)
	JNS    sequenceDecs_decodeSync_bmi2_main_loop
	JMP    loop_finished

copy_1_long:
	MOVQ $0x00000010, R14

copy_1_loop:
	MOVUPS (R11)(R14*1), X4
	MOVUPS X4, (R10)(R14*1)
	ADDQ   $0x10, R14
	CMPQ   R14, R13
	JB     copy_1_loop
	JMP    copy_1_done

copy_2_long:
	LEAQ 32(R10), CX
	ADDQ AX, R10
	ADDQ $0x20, R13
	SUBQ $0x20, AX

copy_2:
	MOVUPS (R13), X4
	MOVUPS 16(R13), X5
	MOVUPS X4, (CX)
	MOVUPS X5, 16(CX)
	ADDQ   $0x20, R13
	ADDQ   $0x20, CX
	SUBQ   $0x20, AX
	JHI    copy_2
	JMP    handle_loop

	// Copy overlapping match
copy_overlapping_match:
	ADDQ AX, R12
	CMPQ CX, $0x10
	JB   copy_overlap_lt16
	MOVQ R10, CX
	ADDQ AX, R10

copy_3:
	MOVUPS (R13), X4
	MOVUPS X4, (CX)
	ADDQ   $0x10, R13
	ADDQ   $0x10, CX
	SUBQ   $0x10, AX
	JHI    copy_3
	JMP    handle_loop

copy_overlap_lt16:
	CMPQ CX, $0x08
	JB   copy_overlap_lt8
	MOVQ R10, CX
	ADDQ AX, R10

copy_3_8:
	MOVQ (R13), R14
	MOVQ R14, (CX)
	ADDQ $0x08, R13
	ADDQ $0x08, CX
	SUBQ $0x08, AX
	JHI  copy_3_8
	JMP  handle_loop

copy_overlap_lt8:
	CMPQ    CX, $0x01
	JNE     copy_slow_3
	MOVQ    R10, CX
	ADDQ    AX, R10
	MOVBQZX (R13), R13
	MOVQ    R13, R14
	SHLQ    $0x08, R14
	ORQ     R14, R13
	MOVQ    R13, R14
	SHLQ    $0x10, R14
	ORQ     R14, R13
	MOVQ    R13, R14
	SHLQ    $0x20, R14
	ORQ     R14, R13

copy_3_1:
	MOVQ R13, (CX)
	ADDQ $0x08, CX
	SUBQ $0x08, AX
	JHI  copy_3_1
	JMP  handle_loop

copy_slow_3:
	MOVBQZX (R13), CX
	MOVB    CL, (R10)
	INCQ    R13
	INCQ    R10
	DECQ    AX
	JNZ     copy_slow_3
	JMP     handle_loop

	// Copy match from history (out-of-line)
copy_from_history:
	MOVQ R12, R13
	ADDQ 32(SP), R13
	CMPQ CX, R13
	JG   error_match_off_too_big_save
	MOVQ CX, R13
	SUBQ R12, R13
	MOVQ 40(SP), R14
	SUBQ R13, R14
	CMPQ AX, R13
	JG   copy_all_from_history
	MOVQ AX, CX
	SUBQ $0x10, CX
	JB   copy_4_small

copy_4_loop:
	MOVUPS (R14), X4
	MOVUPS X4, (R10)
	ADDQ   $0x10, R14
	ADDQ   $0x10, R10
	SUBQ   $0x10, CX
	JAE    copy_4_loop
	LEAQ   16(R14)(CX*1), R14
	LEAQ   16(R10)(CX*1), R10
	MOVUPS -16(R14), X4
	MOVUPS X4, -16(R10)
	JMP    copy_4_end

copy_4_small:
	CMPQ AX, $0x03
	JE   copy_4_move_3
	CMPQ AX, $0x08
	JB   copy_4_move_4through7
	JMP  copy_4_move_8through16

copy_4_move_3:
	MOVWQZX (R14), CX
	MOVB    2(R14), R13
	MOVW    CX, (R10)
	MOVB    R13, 2(R10)
	ADDQ    AX, R14
	ADDQ    AX, R10
	JMP     copy_4_end

copy_4_move_4through7:
	MOVL (R14), CX
	MOVL -4(R14)(AX*1), R13
	MOVL CX, (R10)
	MOVL R13, -4(R10)(AX*1)
	ADDQ AX, R14
	ADDQ AX, R10
	JMP  copy_4_end

copy_4_move_8through16:
	MOVQ (R14), CX
	MOVQ -8(R14)(AX*1), R13
	MOVQ CX, (R10)
	MOVQ R13, -8(R10)(AX*1)
	ADDQ AX, R14
	ADDQ AX, R10

copy_4_end:
	ADDQ AX, R12
	DECQ 16(SP)
	JNS  sequenceDecs_decodeSync_bmi2_main_loop
	JMP  loop_finished

copy_all_from_history:
	MOVQ R13, R15
	SUBQ $0x10, R15
	JB   copy_5_small

copy_5_loop:
	MOVUPS (R14), X4
	MOVUPS X4, (R10)
	ADDQ   $0x10, R14
	ADDQ   $0x10, R10
	SUBQ   $0x10, R15
	JAE    copy_5_loop
	LEAQ   16(R14)(R15*1), R14
	LEAQ   16(R10)(R15*1), R10
	MOVUPS -16(R14), X4
	MOVUPS X4, -16(R10)
	JMP    copy_5_end

copy_5_small:
	CMPQ R13, $0x03
	JE   copy_5_move_3
	JB   copy_5_move_1or2
	CMPQ R13, $0x08
	JB   copy_5_move_4through7
	JMP  copy_5_move_8through16

copy_5_move_1or2:
	MOVB (R14), R15
	MOVB -1(R14)(R13*1), BP
	MOVB R15, (R10)
	MOVB BP, -1(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10
	JMP  copy_5_end

copy_5_move_3:
	MOVWQZX (R14), R15
	MOVB    2(R14), BP
	MOVW    R15, (R10)
	MOVB    BP, 2(R10)
	ADDQ    R13, R14
	ADDQ    R13, R10
	JMP     copy_5_end

copy_5_move_4through7:
	MOVL (R14), R15
	MOVL -4(R14)(R13*1), BP
	MOVL R15, (R10)
	MOVL BP, -4(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10
	JMP  copy_5_end

copy_5_move_8through16:
	MOVQ (R14), R15
	MOVQ -8(R14)(R13*1), BP
	MOVQ R15, (R10)
	MOVQ BP, -8(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10

copy_5_end:
	ADDQ R13, R12
	SUBQ R13, AX
	JMP  copy_match

error_match_off_too_big_save:
	MOVQ ctx+16(FP), AX
	MOVQ CX, 224(AX)
	JMP  error_match_off_too_big

handle_loop:
	DECQ 16(SP)
	JNS  sequenceDecs_decodeSync_bmi2_main_loop

loop_finished:
	MOVQ    s+0(FP), AX
	MOVQ    X7, CX
	MOVQ    CX, 144(AX)
	MOVQ    X8, CX
	MOVQ    CX, 152(AX)
	MOVQ    X9, CX
	MOVQ    CX, 160(AX)
	MOVQ    X3, AX
	MOVQ    ctx+16(FP), CX
	MOVQ    AX, 104(CX)
	XORQ    AX, AX
	SHRXQ   BX, DX, DX
	CMPQ    BX, $0x40
	CMOVQCC AX, DX
	MOVQ    br+8(FP), AX
	MOVQ    DX, 24(AX)
	MOVB    BL, 40(AX)
	SUBQ    (SP), SI
	MOVQ    SI, 32(AX)

	// s.seqSize += outPosition - ctx.outPosition
	MOVQ ctx+16(FP), AX
	MOVQ s+0(FP), CX
	MOVQ R12, DX
	SUBQ 136(AX), DX
	ADDQ DX, 256(CX)

	// Update the context
	MOVQ ctx+16(FP), AX
	MOVQ R12, 136(AX)
	MOVQ 144(AX), CX
	SUBQ CX, R11
	MOVQ R11, 168(AX)

	// Return success
	MOVQ $0x00000000, ret+24(FP)
	RET

sequenceDecs_decodeSync_bmi2_fill_byte_by_byte:
sequenceDecs_decodeSync_bmi2_fill_bbb_loop:
	CMPQ    SI, (SP)
	JBE     sequenceDecs_decodeSync_bmi2_fill_check_overread
	CMPQ    BX, $0x07
	JLE     sequenceDecs_decodeSync_bmi2_fill_end
	SUBQ    $0x01, SI
	SUBQ    $0x08, BX
	MOVBQZX (SI), AX
	SHLXQ   BX, AX, AX
	ORQ     AX, DX
	JMP     sequenceDecs_decodeSync_bmi2_fill_bbb_loop

sequenceDecs_decodeSync_bmi2_fill_check_overread:
	CMPQ BX, $0x40
	JA   error_overread
	JMP  sequenceDecs_decodeSync_bmi2_fill_end

sequenceDecs_decodeSync_bmi2_fill_2_byte_by_byte:
sequenceDecs_decodeSync_bmi2_fill_2_bbb_loop:
	CMPQ    SI, (SP)
	JBE     sequenceDecs_decodeSync_bmi2_fill_2_check_overread
	CMPQ    BX, $0x07
	JLE     sequenceDecs_decodeSync_bmi2_fill_2_end
	SUBQ    $0x01, SI
	SUBQ    $0x08, BX
	MOVBQZX (SI), AX
	SHLXQ   BX, AX, AX
	ORQ     AX, DX
	JMP     sequenceDecs_decodeSync_bmi2_fill_2_bbb_loop

sequenceDecs_decodeSync_bmi2_fill_2_check_overread:
	CMPQ BX, $0x40
	JA   error_overread
	JMP  sequenceDecs_decodeSync_bmi2_fill_2_end

sequenceDecs_decodeSync_bmi2_adjust_offsetB_1_or_0:
	MOVQ  X6, AX
	TESTQ AX, AX
	JNE   sequenceDecs_decodeSync_bmi2_adjust_offset_maybezero
	INCQ  CX
	JMP   sequenceDecs_decodeSync_bmi2_adjust_offset_nonzero

sequenceDecs_decodeSync_bmi2_adjust_offset_maybezero:
	TESTQ CX, CX
	JNZ   sequenceDecs_decodeSync_bmi2_adjust_offset_nonzero
	MOVQ  X7, CX
	JMP   sequenceDecs_decodeSync_bmi2_after_adjust

sequenceDecs_decodeSync_bmi2_adjust_offset_nonzero:
	CMPQ CX, $0x01
	JEQ  sequenceDecs_decodeSync_bmi2_adjust_one
	CMPQ CX, $0x02
	JEQ  sequenceDecs_decodeSync_bmi2_adjust_two
	MOVQ X7, AX
	DECQ AX
	JNZ  sequenceDecs_decodeSync_bmi2_adjust_shift_all
	MOVQ $0x00000001, AX
	JMP  sequenceDecs_decodeSync_bmi2_adjust_shift_all

sequenceDecs_decodeSync_bmi2_adjust_one:
	MOVQ  X8, AX
	MOVOA X7, X8
	MOVQ  AX, X7
	MOVQ  AX, CX
	JMP   sequenceDecs_decodeSync_bmi2_after_adjust

sequenceDecs_decodeSync_bmi2_adjust_two:
	MOVQ X9, AX

sequenceDecs_decodeSync_bmi2_adjust_shift_all:
	MOVOA X8, X9
	MOVOA X7, X8
	MOVQ  AX, X7
	MOVQ  AX, CX
	JMP   sequenceDecs_decodeSync_bmi2_after_adjust

sequenceDecs_decodeSync_bmi2_check_ml_zero:
	TESTQ AX, AX
	JNZ   sequenceDecs_decodeSync_bmi2_error_match_len_ofs_mismatch
	JMP   sequenceDecs_decodeSync_bmi2_match_len_ofs_ok

	// Return with match length error
sequenceDecs_decodeSync_bmi2_error_match_len_ofs_mismatch:
	MOVQ X5, AX
	MOVQ ctx+16(FP), CX
	MOVQ AX, 216(CX)
	MOVQ $0x00000001, ret+24(FP)
	RET

	// Return with match too long error
sequenceDecs_decodeSync_bmi2_error_match_len_too_big:
	MOVQ ctx+16(FP), AX
	MOVQ X5, CX
	MOVQ CX, 216(AX)
	MOVQ $0x00000002, ret+24(FP)
	RET

	// Return with match offset too long error
error_match_off_too_big:
	MOVQ ctx+16(FP), AX
	MOVQ R12, 136(AX)
	MOVQ $0x00000003, ret+24(FP)
	RET

	// Return with not enough literals error
error_not_enough_literals:
	MOVQ ctx+16(FP), AX
	MOVQ X3, CX
	MOVQ CX, 104(AX)
	MOVQ X6, CX
	MOVQ CX, 208(AX)
	MOVQ $0x00000004, ret+24(FP)
	RET

	// Return with overread error
error_overread:
	MOVQ $0x00000006, ret+24(FP)
	RET

	// Return with not enough output space error
error_not_enough_space:
	MOVQ ctx+16(FP), AX
	MOVQ X6, CX
	MOVQ CX, 208(AX)
	MOVQ X5, CX
	MOVQ CX, 216(AX)
	MOVQ R12, 136(AX)
	MOVQ $0x00000005, ret+24(FP)
	RET

// func sequenceDecs_decodeSync_56_bmi2(s *sequenceDecs, br *bitReader, ctx *decodeSyncAsmContext) int
// Requires: BMI2, CMOV, SSE, SSE2
TEXT ·sequenceDecs_decodeSync_56_bmi2(SB), $56-32
	MOVQ    br+8(FP), CX
	MOVQ    24(CX), DX
	MOVBQZX 40(CX), BX
	MOVQ    (CX), AX
	MOVQ    32(CX), CX
	MOVQ    AX, (SP)
	LEAQ    8(AX), SI
	MOVQ    SI, 8(SP)
	LEAQ    (AX)(CX*1), SI
	XORQ    AX, AX
	SHLXQ   BX, DX, DX
	CMPQ    BX, $0x40
	CMOVQCC AX, DX
	MOVQ    ctx+16(FP), AX
	MOVQ    72(AX), DI
	MOVQ    80(AX), R8
	MOVQ    88(AX), R9
	MOVQ    (AX), CX
	MOVQ    CX, X0
	MOVQ    24(AX), CX
	MOVQ    CX, X1
	MOVQ    48(AX), CX
	MOVQ    CX, X2
	MOVQ    96(AX), CX
	MOVQ    CX, 16(SP)
	MOVQ    104(AX), CX
	MOVQ    CX, X3
	MOVQ    112(AX), R10
	MOVQ    128(AX), CX
	MOVQ    CX, 24(SP)
	MOVQ    144(AX), R11
	MOVQ    136(AX), R12
	MOVQ    200(AX), CX
	MOVQ    CX, 48(SP)
	MOVQ    176(AX), CX
	MOVQ    CX, 40(SP)
	MOVQ    184(AX), AX
	MOVQ    AX, 32(SP)
	MOVQ    32(SP), AX
	ADDQ    AX, 40(SP)

	// Calculate pointer to s.out[cap(s.out)] (a past-end pointer)
	ADDQ R10, 24(SP)

	// outBase += outPosition
	ADDQ    R12, R10
	MOVQ    s+0(FP), AX
	MOVQ    144(AX), CX
	MOVQ    CX, X7
	MOVQ    152(AX), CX
	MOVQ    CX, X8
	MOVQ    160(AX), AX
	MOVQ    AX, X9
	PCALIGN $0x40

sequenceDecs_decodeSync_56_bmi2_main_loop:
	// Fill bitreader to have enough for the offset and match length.
	CMPQ  SI, 8(SP)
	JB    sequenceDecs_decodeSync_56_bmi2_fill_byte_by_byte
	MOVQ  BX, AX
	SHRQ  $0x03, AX
	SUBQ  AX, SI
	MOVQ  (SI), DX
	ANDQ  $0x07, BX
	SHLXQ BX, DX, DX

sequenceDecs_decodeSync_56_bmi2_fill_end:
	// Update offset
	MOVQ    R9, AX
	MOVBLZX AH, CX
	MOVQ    CX, X10
	SHRQ    $0x20, AX
	MOVQ    DX, R13
	SHLXQ   CX, DX, DX
	ADDQ    CX, BX
	SHRQ    $0x01, R13
	XORQ    $0x3f, CX
	SHRXQ   CX, R13, R13
	ADDQ    R13, AX
	MOVQ    AX, X4

	// Update match length
	MOVQ    R8, AX
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	MOVQ    DX, R13
	SHLXQ   CX, DX, DX
	ADDQ    CX, BX
	SHRQ    $0x01, R13
	XORQ    $0x3f, CX
	SHRXQ   CX, R13, R13
	ADDQ    R13, AX
	MOVQ    AX, X5

	// Update literal length
	MOVQ    DI, AX
	MOVBLZX AH, CX
	SHRQ    $0x20, AX
	MOVQ    DX, R13
	SHLXQ   CX, DX, DX
	ADDQ    CX, BX
	SHRQ    $0x01, R13
	XORQ    $0x3f, CX
	SHRXQ   CX, R13, R13
	ADDQ    R13, AX
	MOVQ    AX, X6
	CMPQ    16(SP), $0x00
	JZ      sequenceDecs_decodeSync_56_bmi2_skip_update
