	ADDQ    AX, BX
	SHRQ    $0x01, CX
	XORQ    $0x3f, AX
	SHRXQ   AX, CX, CX

	// Update Offset State
	BZHIQ R9, CX, AX
	SHRXQ R9, CX, CX
	SHRL  $0x10, R9
	ADDQ  AX, R9

	// Load ctx.ofTable
	MOVQ X2, AX
	MOVQ (AX)(R9*8), R9

	// Update Match Length State
	BZHIQ R8, CX, AX
	SHRXQ R8, CX, CX
	SHRL  $0x10, R8
	ADDQ  AX, R8

	// Load ctx.mlTable
	MOVQ X1, AX
	MOVQ (AX)(R8*8), R8

