sequenceDecs_decodeSync_56_bmi2_skip_update:
	MOVQ X10, AX

	// Adjust offset
	MOVQ  X4, CX
	CMPQ  AX, $0x01
	JBE   sequenceDecs_decodeSync_56_bmi2_adjust_offsetB_1_or_0
	MOVOA X8, X9
	MOVOA X7, X8
	MOVQ  CX, X7

sequenceDecs_decodeSync_56_bmi2_after_adjust:
	// Check values
	MOVQ  X5, AX
	MOVQ  X6, R13
	MOVQ  X3, R14
	SUBQ  R13, R14
	MOVQ  R14, X3
