sequenceDecs_decodeSync_56_bmi2_match_len_ofs_ok:
	// Check if we have enough space in s.out
	LEAQ 32(R13)(AX*1), R14
	ADDQ R10, R14
	CMPQ R14, 24(SP)
	JA   error_not_enough_space

	// Copy literals
	MOVUPS (R11), X4
	MOVUPS X4, (R10)
	CMPQ   R13, $0x10
