copy_1_done:
	ADDQ R13, R11
	ADDQ R13, R10
	ADDQ R13, R12

	// Check offset bounds and fast-path matches inside current buffer
	CMPQ CX, 48(SP)
	JG   error_match_off_too_big_save
	CMPQ CX, R12
	JA   copy_from_history

	// Copy match from the current buffer
copy_match:
	MOVQ R10, R13
	SUBQ CX, R13

