copy_1_loop:
	MOVUPS (R11), X0
	MOVUPS X0, (R10)
	ADDQ   $0x10, R11
	ADDQ   $0x10, R10
	SUBQ   $0x10, R14
	JAE    copy_1_loop
	LEAQ   16(R11)(R14*1), R11
	LEAQ   16(R10)(R14*1), R10
	MOVUPS -16(R11), X0
	MOVUPS X0, -16(R10)
	JMP    copy_1_end

copy_1_small:
	CMPQ R13, $0x03
	JE   copy_1_move_3
	JB   copy_1_move_1or2
	CMPQ R13, $0x08
	JB   copy_1_move_4through7
	JMP  copy_1_move_8through16

copy_1_move_1or2:
	MOVB (R11), R14
	MOVB -1(R11)(R13*1), R15
	MOVB R14, (R10)
	MOVB R15, -1(R10)(R13*1)
	ADDQ R13, R11
	ADDQ R13, R10
	JMP  copy_1_end

copy_1_move_3:
	MOVWQZX (R11), R14
	MOVB    2(R11), R15
	MOVW    R14, (R10)
	MOVB    R15, 2(R10)
	ADDQ    R13, R11
	ADDQ    R13, R10
	JMP     copy_1_end

copy_1_move_4through7:
	MOVL (R11), R14
	MOVL -4(R11)(R13*1), R15
	MOVL R14, (R10)
	MOVL R15, -4(R10)(R13*1)
	ADDQ R13, R11
	ADDQ R13, R10
	JMP  copy_1_end

copy_1_move_8through16:
	MOVQ (R11), R14
	MOVQ -8(R11)(R13*1), R15
	MOVQ R14, (R10)
	MOVQ R15, -8(R10)(R13*1)
	ADDQ R13, R11
	ADDQ R13, R10

copy_1_end:
	ADDQ R13, R12

	// Check offset bounds and fast-path matches inside current buffer
check_offset:
	CMPQ CX, 104(SP)
	JG   error_match_off_too_big_save
