copy_2_loop:
	MOVUPS (R13), X0
	MOVUPS X0, (R10)
	ADDQ   $0x10, R13
	ADDQ   $0x10, R10
	SUBQ   $0x10, CX
	JAE    copy_2_loop
	LEAQ   16(R13)(CX*1), R13
	LEAQ   16(R10)(CX*1), R10
	MOVUPS -16(R13), X0
	MOVUPS X0, -16(R10)
	JMP    copy_2_end

copy_2_small:
	CMPQ AX, $0x03
	JE   copy_2_move_3
	JB   copy_2_move_1or2
	CMPQ AX, $0x08
	JB   copy_2_move_4through7
	JMP  copy_2_move_8through16

copy_2_move_1or2:
	MOVB (R13), CL
	MOVB -1(R13)(AX*1), R14
	MOVB CL, (R10)
	MOVB R14, -1(R10)(AX*1)
	ADDQ AX, R13
	ADDQ AX, R10
	JMP  copy_2_end

copy_2_move_3:
	MOVWQZX (R13), CX
	MOVB    2(R13), R14
	MOVW    CX, (R10)
	MOVB    R14, 2(R10)
	ADDQ    AX, R13
	ADDQ    AX, R10
	JMP     copy_2_end

copy_2_move_4through7:
	MOVL (R13), CX
	MOVL -4(R13)(AX*1), R14
	MOVL CX, (R10)
	MOVL R14, -4(R10)(AX*1)
	ADDQ AX, R13
	ADDQ AX, R10
	JMP  copy_2_end

copy_2_move_8through16:
	MOVQ (R13), CX
	MOVQ -8(R13)(AX*1), R14
	MOVQ CX, (R10)
	MOVQ R14, -8(R10)(AX*1)
	ADDQ AX, R13
	ADDQ AX, R10

copy_2_end:
	JMP handle_loop

