copy_overlapping_match:
	ADDQ AX, R12
	CMPQ CX, $0x10
	JB   copy_overlap_lt16

copy_3_blocks:
	MOVUPS (R13), X0
	MOVUPS X0, (R10)
	ADDQ   $0x10, R13
	ADDQ   $0x10, R10
	SUBQ   $0x10, AX
	CMPQ   AX, $0x10
	JAE    copy_3_blocks
	TESTQ  AX, AX
	JZ     handle_loop
	JMP    copy_slow_3

copy_overlap_lt16:
copy_slow_3:
	MOVBQZX (R13), CX
	MOVB    CL, (R10)
	INCQ    R13
	INCQ    R10
	DECQ    AX
