	SUBQ R13, R14
	CMPQ AX, R13
	JG   copy_all_from_history
	MOVQ AX, CX
	SUBQ $0x10, CX
	JB   copy_4_small

copy_4_loop:
	MOVUPS (R14), X0
	MOVUPS X0, (R10)
	ADDQ   $0x10, R14
	ADDQ   $0x10, R10
	SUBQ   $0x10, CX
	JAE    copy_4_loop
	LEAQ   16(R14)(CX*1), R14
	LEAQ   16(R10)(CX*1), R10
	MOVUPS -16(R14), X0
	MOVUPS X0, -16(R10)
