copy_4_small:
	CMPQ AX, $0x03
	JE   copy_4_move_3
	CMPQ AX, $0x08
	JB   copy_4_move_4through7
	JMP  copy_4_move_8through16

copy_4_move_3:
	MOVWQZX (R14), CX
	MOVB    2(R14), R13
	MOVW    CX, (R10)
	MOVB    R13, 2(R10)
	ADDQ    AX, R14
	ADDQ    AX, R10
