copy_1_loop:
	MOVUPS (R11), X4
	MOVUPS X4, (R10)
	ADDQ   $0x10, R11
	ADDQ   $0x10, R10
	SUBQ   $0x10, R14
	JAE    copy_1_loop
	LEAQ   16(R11)(R14*1), R11
	LEAQ   16(R10)(R14*1), R10
	MOVUPS -16(R11), X4
	MOVUPS X4, -16(R10)
	JMP    copy_1_end

copy_1_small:
