copy_2_loop:
	MOVUPS (R13), X4
	MOVUPS X4, (R10)
	ADDQ   $0x10, R13
	ADDQ   $0x10, R10
	SUBQ   $0x10, CX
	JAE    copy_2_loop
	LEAQ   16(R13)(CX*1), R13
	LEAQ   16(R10)(CX*1), R10
	MOVUPS -16(R13), X4
	MOVUPS X4, -16(R10)
	JMP    copy_2_end

copy_2_small:
	CMPQ AX, $0x03
	JE   copy_2_move_3
	JB   copy_2_move_1or2
	CMPQ AX, $0x08
	JB   copy_2_move_4through7
	JMP  copy_2_move_8through16

copy_2_move_1or2:
	MOVB (R13), CL
