	MOVB CL, (R10)
	MOVB R14, -1(R10)(AX*1)
	ADDQ AX, R13
	ADDQ AX, R10
	JMP  copy_2_end

copy_2_move_3:
	MOVWQZX (R13), CX
	MOVB    2(R13), R14
	MOVW    CX, (R10)
	MOVB    R14, 2(R10)
	ADDQ    AX, R13
	ADDQ    AX, R10
	JMP     copy_2_end

copy_2_move_4through7:
	MOVL (R13), CX
	MOVL -4(R13)(AX*1), R14
	MOVL CX, (R10)
	MOVL R14, -4(R10)(AX*1)
	ADDQ AX, R13
	ADDQ AX, R10
	JMP  copy_2_end

copy_2_move_8through16:
	MOVQ (R13), CX
	MOVQ -8(R13)(AX*1), R14
	MOVQ CX, (R10)
	MOVQ R14, -8(R10)(AX*1)
	ADDQ AX, R13
	ADDQ AX, R10

