	CMPQ AX, $0x03
	JE   copy_4_move_3
	CMPQ AX, $0x08
	JB   copy_4_move_4through7
	JMP  copy_4_move_8through16

copy_4_move_3:
	MOVWQZX (R14), CX
	MOVB    2(R14), R13
	MOVW    CX, (R10)
	MOVB    R13, 2(R10)
	ADDQ    AX, R14
	ADDQ    AX, R10
	JMP     copy_4_end

copy_4_move_4through7:
	MOVL (R14), CX
	MOVL -4(R14)(AX*1), R13
	MOVL CX, (R10)
	MOVL R13, -4(R10)(AX*1)
	ADDQ AX, R14
	ADDQ AX, R10
	JMP  copy_4_end

copy_4_move_8through16:
	MOVQ (R14), CX
	MOVQ -8(R14)(AX*1), R13
	MOVQ CX, (R10)
	MOVQ R13, -8(R10)(AX*1)
