	LEAQ   16(R10)(R15*1), R10
	MOVUPS -16(R14), X4
	MOVUPS X4, -16(R10)
	JMP    copy_5_end

copy_5_small:
	CMPQ R13, $0x03
	JE   copy_5_move_3
	JB   copy_5_move_1or2
	CMPQ R13, $0x08
	JB   copy_5_move_4through7
	JMP  copy_5_move_8through16

copy_5_move_1or2:
	MOVB (R14), R15
