	MOVB R15, (R10)
	MOVB BP, -1(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10
	JMP  copy_5_end

copy_5_move_3:
	MOVWQZX (R14), R15
	MOVB    2(R14), BP
	MOVW    R15, (R10)
	MOVB    BP, 2(R10)
	ADDQ    R13, R14
	ADDQ    R13, R10
	JMP     copy_5_end

copy_5_move_4through7:
	MOVL (R14), R15
	MOVL -4(R14)(R13*1), BP
	MOVL R15, (R10)
	MOVL BP, -4(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10
	JMP  copy_5_end

copy_5_move_8through16:
	MOVQ (R14), R15
	MOVQ -8(R14)(R13*1), BP
	MOVQ R15, (R10)
	MOVQ BP, -8(R10)(R13*1)
	ADDQ R13, R14
	ADDQ R13, R10

copy_5_end:
	ADDQ R13, R12
	SUBQ R13, AX
	JMP  copy_match

